def write_matlab_script(path: Path, km0: float, km1: float, times: list[datetime]):
    t = ",".join(f"datetime({d.year},{d.month:02d},{d.day:02d})" for d in times)
    text = (TEMPLATE.replace("@VERSION@", GENERATOR_VERSION).replace("@TIMES@", t)
            .replace("@KM0@", f"{km0:g}").replace("@KM1@", f"{km1:g}"))
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
